text:
button.account-hub-option-button {
  display: grid;
  grid-template-columns: auto 1fr;
  grid-template-rows: auto auto;
  column-gap: var(--hub-address-book-option-select-gap);
  row-gap: 1px;
  padding: var(--hub-address-book-option-padding);
  margin: 0;
  border: none;
  background-color: var(--color-surface-base);
  inline-size: 100%;
  box-shadow:
    0 12px 10px -10px rgba(0, 79, 155, 0.25),
    0 0 5px 0 rgba(23, 95, 182, 0.1);
  overflow: hidden;
  flex-shrink: 0;

  &.three-column {
    grid-template-columns: auto 1fr auto;
  }

  @media (prefers-reduced-motion: no-preference) {
    transition:
      background-color 220ms ease,
      box-shadow 220ms ease;
  }

  &:enabled {
    &:hover,
    &:hover:active {
      background-color: var(--color-primary-soft);

      & .option-icon {
        background-color: var(--color-primary-pressed);
      }
    }

    &:hover {
      box-shadow:
        0 25px 10px -20px rgba(0, 79, 155, 0.35),
        0 0 5px 0 rgba(23, 95, 182, 0.2);
    }

    &:hover:active {
      box-shadow:
        0 5px 5px -5px rgba(0, 79, 155, 0.35),
        0 0 5px 0 rgba(23, 95, 182, 0.2);
    }
  }

  &:disabled {
    background-color: var(--color-surface-border);

    & .option-title.account-title,
    & .option-data.account-data {
      color: var(--color-text-secondary);
    }

    & .account-address-book-count {
      background-color: var(--color-text-secondary);
    }

    & .mail-lock-icon {
      stroke: var(--color-text-secondary);
      fill: color-mix(in srgb, var(--color-text-secondary) 20%, transparent);
    }
  }

  & img {
    grid-column: 1;
    grid-row: 1 / span 2;
    -moz-context-properties: fill, stroke;
    fill: color-mix(in srgb, var(--color-surface-base) 20%, transparent);
    stroke: var(--color-surface-base);
    align-self: center;
    line-height: 0;

    .fetching & {
      stroke: var(--color-primary-default);
      background-color: transparent !important;
      box-shadow: none !important;
    }

    &.address-book-option-icon {
      padding: 6px;
      background-color: var(--color-primary-default);
      box-shadow:
        0 3px 4px -2px rgba(25, 81, 143, 0.5),
        0 -2px 0 0 rgb(0, 0, 0, 0.25) inset;
      border-radius: 5px;
    }

    @media (prefers-reduced-motion: no-preference) {
      transition: background-color 220ms ease;

      .fetching & {
        animation: spinning-animation 1.5s ease infinite;
      }
    }

    &.sync-icon {
      content: var(--icon-sync-lg);
    }

    &.remote-address-book-icon {
      content: var(--icon-address-book-remote-lg);
    }

    &.local-address-book-icon {
      content: var(--icon-address-book-new-lg);
    }

    &.ldap-address-book-icon {
      content: var(--addons-manager-site-permissions);
    }

    &.mail-lock-icon {
      stroke: var(--color-primary-default);
      fill: color-mix(in srgb, var(--color-primary-default) 20%, transparent);
      content: var(--icon-mail-lock-lg);
    }
  }

  & .option-title {
    grid-column: 2;
    grid-row: 1;
    font-size: 1.54rem;
    color: var(--color-primary-hover);
    font-weight: 400;
    text-align: start;
    text-overflow: ellipsis;

    &.account-title {
      font-size: 1.15rem;
      color: var(--color-text-secondary);
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }
  }
